use vstd::prelude::*;
use vstd::vec::*;

verus! {

pub fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i && i < a.len() ==> result[i] == a[i],
{
    let mut result = Vec::new();
    let mut idx: usize = 0;
    
    while idx < a.len()
        invariant
            idx <= a.len(),
            result.len() == idx,
            forall|i: int| 0 <= i && i < idx ==> result[i] == a[i],
        decreases a.len() - idx,
    {
        let elem = a[idx];
        result.push(elem);
        idx = idx + 1;
    }
    
    result
}

#[verifier(external)]
fn main() {
    let v = vec![1, 2, 3, 4, 5];
    let copied = copy(&v);
    println!("Original: {:?}", v);
    println!("Copied: {:?}", copied);
    assert!(copied.len() == v.len());
    for i in 0..v.len() {
        assert!(copied[i] == v[i]);
    }
}

} // verus!